{"command":"cd ~/Documents/ocean_ai_real && node -e "
const zlib=require('node:zlib'), fs=require('node:fs');
const p='/Users/zhihaomeng/.dsh/sessions/--Users-zhihaomeng-Documents-ocean_ai_real--/session-fbf0c869-7f7c-407a-ad3c-ec0ce7d681c3/session.v4.jsonl.zstd';
const chunks=[];
const d=zlib.createZstdDecompress();
let done=new Promise(r=>d.on('end',r));
d.on('data',c=>chunks.push(c));
fs.createReadStream(p).pipe(d);
done.then(()=>{
  const txt=Buffer.concat(chunks).toString('utf8');
  const lines=txt.split('\n').filter(Boolean);
  console.log('decompressed bytes',txt.length,'lines',lines.length);
  const types={};
  for(const l of lines){try{const o=JSON.parse(l);types[o.type]=(types[o.type]||0)+1;}catch(e){}}
  console.log('types:',JSON.stringify(types,null,1));
  const tl=lines.map(l=>{try{return JSON.parse(l)}catch(e){return null}}).filter(Boolean);
  console.log('--- sample records ---');
  for(const t of ['user','assistant','tool-call','tool-result','message']){
    const s=tl.find(x=>x.type===t); if(s) console.log(t,':',JSON.stringify(s).slice(0,400));
  }
});
" 2>&1 | head -40","description":"Stream-decompress session and list record types"}

