{"command":"cd ~/Documents/ocean_ai_real && node -e "
const zlib=require('node:zlib'), fs=require('node:fs');
const p='/Users/zhihaomeng/.dsh/sessions/--Users-zhihaomeng-Documents-ocean_ai_real--/session-fbf0c869-7f7c-407a-ad3c-ec0ce7d681c3/session.v4.jsonl.zstd';
const buf=fs.readFileSync(p);
const magic=Buffer.from([0x28,0xb5,0x2f,0xfd]);
let offs=[],i=-1; while((i=buf.indexOf(magic,i+1))!==-1) offs.push(i);
offs.push(buf.length);
let ok=0,fail=0,text='';
for(let k=0;k<offs.length-1;k++){
  try{ text+=zlib.zstdDecompressSync(buf.slice(offs[k],offs[k+1])).toString('utf8'); ok++; }
  catch(e){ fail++; }
}
console.log('frames ok',ok,'fail',fail,'text bytes',text.length);
const lines=text.split('\n').filter(Boolean);
console.log('lines',lines.length);
const types={}; const recs=[];
for(const l of lines){try{const o=JSON.parse(l);types[o.type]=(types[o.type]||0)+1;recs.push(o);}catch(e){types['PARSE_FAIL']=(types['PARSE_FAIL']||0)+1}}
console.log('types:',JSON.stringify(types,null,1));
console.log('--- role sample ---');
const a=recs.find(r=>r.type==='assistant'); console.log('ASSISTANT keys',a&&Object.keys(a));
console.log(JSON.stringify(a).slice(0,600));
const u=recs.find(r=>r.type==='user'); console.log('USER', JSON.stringify(u).slice(0,300));
" 2>&1 | head -50","description":"Decompress session frame-by-frame and inspect records"}

